/**
 * Browser download of generated bytes, shared by every web delivery path:
 * the backup export's web branch and the Profit & Loss export both hand an
 * object URL to a synthetic anchor click and revoke it afterwards. The DOM
 * is only touched at call time, so native bundles carry the module harmlessly
 * (the function never runs there).
 */
export function downloadBytes(
  bytes: Uint8Array,
  mimeType: string,
  fileName: string,
): void {
  // TS 5.9's lib.dom narrows BlobPart to ArrayBuffer-backed views, while the
  // workbook arrives as a plain Uint8Array; at runtime Blob accepts any view.
  const blob = new Blob([bytes as unknown as BlobPart], { type: mimeType });
  let url: string | undefined;
  let link: HTMLAnchorElement | undefined;
  try {
    // Everything after the Blob is created inside the try: a createElement,
    // attribute, or append failure must still reach the finally's revoke.
    link = document.createElement('a');
    url = URL.createObjectURL(blob);
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
  } finally {
    try {
      if (link) document.body.removeChild(link);
    } catch {
      // Cleanup is best effort; the click error is the one to surface.
    }
    if (url) {
      // Firefox/Safari may still be resolving the URL when click() returns:
      // keep it alive for a tick before revoking, also when anything above
      // threw, so a failed download never leaks the object URL.
      setTimeout(() => URL.revokeObjectURL(url as string), 0);
    }
  }
}
